# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DAILY &amp; STUDY ROUTINES AND CLASSROOM RULES (THEME 2)</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Study Routines &amp; Learning Activities</text>\n  <text x="180" y="98" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• review / revise notes (notları gözden geçirmek)</text>\n  <text x="180" y="120" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• focus on the task (göreve odaklanmak)</text>\n  <text x="180" y="142" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• work in pairs / groups (ikili / grupça çalışmak)</text>\n  <text x="180" y="164" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• read silently / aloud (sessizce / sesli okumak)</text>\n  <text x="180" y="186" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• keep a learning diary (öğrenme günlüğü tutmak)</text>\n  <text x="180" y="208" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• do research / practise (araştırma / pratik yapmak)</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Classroom Rules &amp; Responsibilities</text>\n  <text x="520" y="98" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#14532d">• have to / must + V1 (Zorunluluk ve Kural)</text>\n  <text x="520" y="120" text-anchor="middle" font-size="11" fill="#334155">We must listen to each other in turns.</text>\n  <text x="520" y="144" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#14532d">• Do we have to ...? (Yapmak zorunda mıyız?)</text>\n  <text x="520" y="166" text-anchor="middle" font-size="11" fill="#334155">Do we have to discuss the answers in pairs?</text>\n  <text x="520" y="190" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#14532d">• Be responsible for / Recycle paper &amp; plastic</text>\n  <text x="520" y="210" text-anchor="middle" font-size="11" fill="#334155">Sınıf düzeni ve geri dönüşüm sorumlulukları</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PRESENT SIMPLE VS. PRESENT CONTINUOUS (PROGRESSIVE)</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Simple Present Tense (Geniş Zaman)</text>\n  <text x="180" y="98" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#854d0e">Kullanım: Alışkanlıklar ve Rutinler (Habits)</text>\n  <text x="180" y="122" text-anchor="middle" font-size="11.5" fill="#713f12">• I / You / We / They + V1 (review, study)</text>\n  <text x="180" y="144" text-anchor="middle" font-size="11.5" fill="#713f12">• He / She / It + V-s/es/ies (reviews, brushes)</text>\n  <text x="180" y="170" text-anchor="middle" font-size="11" font-weight="bold" fill="#a16207">Zaman İpuçları (Time Expressions):</text>\n  <text x="180" y="190" text-anchor="middle" font-size="11" fill="#475569">always, usually, normally, often, sometimes,</text>\n  <text x="180" y="208" text-anchor="middle" font-size="11" fill="#475569">every day, on Mondays, How often...?</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Present Continuous (Şimdiki Zaman)</text>\n  <text x="520" y="98" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">Kullanım: Şu An Yapılan Eylemler (Right Now)</text>\n  <text x="520" y="122" text-anchor="middle" font-size="11.5" fill="#581c87">• I am + V-ing (I am reviewing my notes now.)</text>\n  <text x="520" y="144" text-anchor="middle" font-size="11.5" fill="#581c87">• He / She / It is + V-ing · We / They are + V-ing</text>\n  <text x="520" y="170" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">Zaman İpuçları (Time Expressions):</text>\n  <text x="520" y="190" text-anchor="middle" font-size="11" fill="#475569">now, right now, at the moment, today,</text>\n  <text x="520" y="208" text-anchor="middle" font-size="11" fill="#475569">Look!, Listen! (Konuşma anındaki eylem)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">QUESTION TAGS, POSSESSIVE ADJECTIVES &amp; NUMBERS</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Question Tags (Değil mi? - Eklenti Soruları)</text>\n  <text x="180" y="100" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#155e75">Olumlu Cümle (+) ➔ Olumsuz Tag (-)</text>\n  <text x="180" y="120" text-anchor="middle" font-size="11" fill="#0f172a">• She is marking the tests now, isn\'t she?</text>\n  <text x="180" y="140" text-anchor="middle" font-size="11" fill="#0f172a">• They study in the library, don\'t they?</text>\n  <text x="180" y="166" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#155e75">Olumsuz Cümle (-) ➔ Olumlu Tag (+)</text>\n  <text x="180" y="186" text-anchor="middle" font-size="11" fill="#0f172a">• He doesn\'t read aloud, does he?</text>\n  <text x="180" y="206" text-anchor="middle" font-size="11" fill="#0f172a">• You aren\'t sleeping now, are you?</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Possessive Adjectives &amp; Numbers</text>\n  <text x="520" y="98" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9f1239">İyelik Sıfatları: my, your, his, her, its, our, their</text>\n  <text x="520" y="118" text-anchor="middle" font-size="11" fill="#475569">I keep my diary on the desk. He brushes his teeth.</text>\n  <text x="520" y="146" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9f1239">Cardinals (100-500) &amp; Ordinals (1st-50th):</text>\n  <text x="520" y="166" text-anchor="middle" font-size="11" fill="#475569">• 245: two hundred and forty-five</text>\n  <text x="520" y="186" text-anchor="middle" font-size="11" fill="#475569">• 1st (first), 2nd (second), 3rd (third), 20th (twentieth)</text>\n  <text x="520" y="206" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">• 24th of November: Teachers\' Day</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
